55	  readonly id: InvitationId;
56	  readonly email: string;
57	  readonly role: Role;
58	  readonly invitedBy: UserId;
59	  readonly token: string;
60	  readonly expiresAt: IsoTimestamp;
61	  readonly acceptedAt: IsoTimestamp | null;
62	  readonly revokedAt: IsoTimestamp | null;
63	}
