65	/**
66	 * The authenticated principal for one request, always resolved for exactly one
67	 * organization. Everything that authorizes a mutation takes an `Actor` — see
68	 * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in
69	 * `src/lib/tenant.ts`.
70	 */
71	export interface Actor {
72	  readonly userId: UserId;
73	  readonly orgId: OrgId;
